/*
 * rn_infer.c — integer-only RadarNet-1D, bit-exact with python/int_quant.py
 * ==========================================================================
 * The software baseline for the same model the accelerator runs: plain C,
 * INT8 weights/activations, INT32 accumulation, the same fixed-point
 * requantization. Builds for the host (verification) and for the Zynq's
 * Cortex-A9 (latency/energy baseline). Weights come from rn_model.h,
 * generated by `int_quant.py export-c`.
 */
#include "rn_infer.h"
#include "rn_model.h"

#define L0 128

static int8_t sat8(int64_t v)
{
    return (int8_t)(v > 127 ? 127 : (v < -128 ? -128 : v));
}

/*
 * y[oc][t] = sat8(relu?(((Σ w·x + b)·M[oc] + (skip·Ms << SK) + 2^(SH-1)) >> SH))
 * x: [ic][lin], y: [oc][lout], skip: [oc][lout] or NULL
 */
static void conv1d(const int8_t *x, int ic, int lin, int8_t *y, int oc, int k, int s, int p,
                   const int8_t *w, const int32_t *b, const int32_t *m, int sh,
                   int relu, const int8_t *skip, int ms, int sk)
{
    const int lout = (lin + 2 * p - k) / s + 1;
    const int64_t rnd = (int64_t)1 << (sh - 1);
    for (int o = 0; o < oc; o++) {
        const int8_t *wo = w + o * ic * k;
        for (int t = 0; t < lout; t++) {
            int32_t acc = b[o];
            for (int c = 0; c < ic; c++) {
                const int8_t *xc = x + c * lin;
                const int8_t *wc = wo + c * k;
                for (int j = 0; j < k; j++) {
                    int pos = t * s + j - p;
                    if (pos >= 0 && pos < lin)
                        acc += (int32_t)wc[j] * xc[pos];
                }
            }
            int64_t v = (int64_t)acc * m[o];
            if (skip)
                v += ((int64_t)skip[o * lout + t] * ms) << sk;
            v = (v + rnd) >> sh;               /* arithmetic shift (gcc, two's complement) */
            if (relu && v < 0)
                v = 0;
            y[o * lout + t] = sat8(v);
        }
    }
}

int rn_infer(const int8_t in_iq[2 * L0], int32_t logits[RN_NUM_CLASSES])
{
    static int8_t a1[16 * 128], a2[32 * 64], b1h[32 * 64], b1o[32 * 64];
    static int8_t pr[64 * 32], b2h[64 * 32], b2o[64 * 32];
    int8_t gap[64];

    conv1d(in_iq, 2, 128, a1, 16, 7, 1, 3, L1_w, L1_b, L1_m, L1_SH, 1, 0, 0, 0);
    conv1d(a1, 16, 128, a2, 32, 3, 2, 1, L2_w, L2_b, L2_m, L2_SH, 1, 0, 0, 0);
    conv1d(a2, 32, 64, b1h, 32, 3, 1, 1, RB1C1_w, RB1C1_b, RB1C1_m, RB1C1_SH, 1, 0, 0, 0);
    conv1d(b1h, 32, 64, b1o, 32, 3, 1, 1, RB1C2_w, RB1C2_b, RB1C2_m, RB1C2_SH, 1,
           a2, RB1C2_MS, RB1C2_SK);
    conv1d(b1o, 32, 64, pr, 64, 1, 2, 0, RB2P_w, RB2P_b, RB2P_m, RB2P_SH, 0, 0, 0, 0);
    conv1d(b1o, 32, 64, b2h, 64, 3, 2, 1, RB2C1_w, RB2C1_b, RB2C1_m, RB2C1_SH, 1, 0, 0, 0);
    conv1d(b2h, 64, 32, b2o, 64, 3, 1, 1, RB2C2_w, RB2C2_b, RB2C2_m, RB2C2_SH, 1,
           pr, RB2C2_MS, RB2C2_SK);

    for (int c = 0; c < 64; c++) {               /* GAP: rounding divide by 32 */
        int32_t sum = 0;
        for (int t = 0; t < 32; t++)
            sum += b2o[c * 32 + t];
        gap[c] = sat8((sum + 16) >> 5);
    }
    int best = 0;
    for (int o = 0; o < RN_NUM_CLASSES; o++) {   /* FC, raw INT32 logits + argmax */
        int32_t acc = FC_b[o];
        for (int c = 0; c < 64; c++)
            acc += (int32_t)FC_w[o * 64 + c] * gap[c];
        logits[o] = acc;
        if (acc > logits[best])
            best = o;
    }
    return best;
}
